class Account:
    def __init__(self, balance):
        self.balance = balance

    def withdraw(self, amt):
        if amt > self.balance:
            return "Insufficient"
        self.balance -= amt
        return self.balance

acc = Account(500)
print(acc.withdraw(200), acc.withdraw(400), acc.withdraw(300))
